                            {t.status === 'active' ? <CheckCircle className="w-3.5 h-3.5 text-success" /> : <XCircle className="w-3.5 h-3.5 text-destructive" />}
                            <span className="text-xs capitalize">{t.status}</span>
                          </div>
                        </TableCell>
                        <TableCell className="text-sm text-muted-foreground">
                          {new Date(t.createdAt).toLocaleDateString()}
                        </TableCell>
                        <TableCell>
                          <Button variant="ghost" size="icon" className="h-8 w-8">
                            <MoreVertical className="w-4 h-4" />
                          </Button>
                        </TableCell>
                      </TableRow>
                    ))
                  )}
                </TableBody>
              </Table>
            </CardContent>
          </Card>
        )}

        {tab === "plans" && (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {plansLoading ? (
              <div className="col-span-3 text-center py-10 text-muted-foreground animate-pulse">Loading plans...</div>
            ) : plans.length === 0 ? (
              <div className="col-span-3 text-center py-10 text-muted-foreground">No plans configured yet.</div>
            ) : (
              plans.map((p: any) => (
                <Card key={p.id} className="shadow-card">
                  <CardHeader>
                    <CardTitle className="text-lg font-heading">{p.name}</CardTitle>
                    <p className="text-2xl font-bold text-primary">
                      KES {Number(p.priceMonthly || p.price || 0).toLocaleString()}/mo
                    </p>
                  </CardHeader>
                  <CardContent className="space-y-3">
                    <div className="flex justify-between text-sm">
                      <span className="text-muted-foreground">Status</span>
                      <Badge className={p.isActive !== false ? 'bg-success/10 text-success' : 'bg-destructive/10 text-destructive'}>
                        {p.isActive !== false ? 'Active' : 'Inactive'}
                      </Badge>
                    </div>
                    <div className="flex justify-between text-sm">
                      <span className="text-muted-foreground">Max Students</span>
                      <span className="font-medium">{p.limits?.maxStudents?.toLocaleString() || "Unlimited"}</span>
                    </div>
                    {p.description && (
                      <p className="text-xs text-muted-foreground pt-2">{p.description}</p>
                    )}
                    <Button variant="outline" size="sm" className="w-full mt-2">Edit Plan</Button>
                  </CardContent>
                </Card>
              ))
            )}
          </div>
        )}

        {tab === "billing" && (
          <Card className="shadow-card">
            <CardHeader>
              <CardTitle className="text-base font-heading">Revenue Overview</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="text-center py-6">
                <p className="text-3xl font-bold text-primary">KES {totalRevenue.toLocaleString()}</p>
                <p className="text-sm text-muted-foreground mt-1">Total platform revenue collected</p>
                <Button variant="outline" className="mt-4" onClick={() => navigate("/owner/billing")}>
                  View Full Billing Dashboard
                </Button>
              </div>
            </CardContent>
          </Card>
        )}
      </div>
    </div>
  );
}

import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Lock, Mail, School } from "lucide-react";
import { toast } from "sonner";
import api from "@/lib/api";

export default function OwnerLogin() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      const res = await api.post("/owner/auth/login", { email, password });
      localStorage.setItem("owner_token", res.data.access_token);
      toast.success("Welcome, Platform Admin");
      navigate("/owner/dashboard");
    } catch (err: any) {
      const msg = err?.response?.data?.message || "Invalid credentials";
      toast.error(msg);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen gradient-sidebar flex items-center justify-center p-6">
      <Card className="w-full max-w-md shadow-2xl border-sidebar-border bg-sidebar/50 backdrop-blur-xl">
        <CardHeader className="text-center space-y-1">
          <div className="mx-auto w-12 h-12 rounded-xl bg-primary flex items-center justify-center mb-4">
            <School className="w-7 h-7 text-primary-foreground" />
          </div>
          <CardTitle className="text-2xl font-heading font-bold text-white">Owner Portal</CardTitle>
          <CardDescription className="text-sidebar-foreground/60">
            System administration for ShuleCloud
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleLogin} className="space-y-4">
            <div className="relative">
              <Mail className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-sidebar-foreground/40" />
              <Input
                type="email"
                placeholder="admin@shulecloud.co.ke"
                className="pl-10 bg-sidebar-accent/50 border-sidebar-border text-white placeholder:text-sidebar-foreground/30"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
              />
            </div>
            <div className="relative">
              <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-sidebar-foreground/40" />
              <Input
                type="password"
                placeholder="••••••••"
                className="pl-10 bg-sidebar-accent/50 border-sidebar-border text-white placeholder:text-sidebar-foreground/30"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
              />
            </div>
            <Button type="submit" className="w-full" disabled={loading}>
              {loading ? "Authenticating..." : "Sign In to Control Center"}
            </Button>
          </form>
          <div className="mt-6 pt-6 border-t border-sidebar-border text-center space-y-2">
            <p className="text-sm text-sidebar-foreground/60">
              Don't have an account?{" "}
              <Link to="/owner/register" className="text-primary font-semibold hover:underline">
                Register
              </Link>
            </p>
            <p className="text-xs text-sidebar-foreground/40 font-mono tracking-widest uppercase">
              Authorized Access Only
            </p>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import api from "@/lib/api";
import { Card, CardContent, CardHeader, CardTitle, CardDescription, CardFooter } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Plus, CreditCard, Users, Database, Globe, MoreVertical, Edit2, Trash2, Package, Check, ChevronRight } from "lucide-react";
import { toast } from "sonner";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter, DialogTrigger } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { motion, AnimatePresence } from "framer-motion";

export default function OwnerPlans() {
    const queryClient = useQueryClient();

    const { data: plans = [], isLoading } = useQuery({
        queryKey: ["owner-plans"],
        queryFn: async () => {
            const res = await api.get("/owner/plans");
            return res.data;
        }
    });

    const [isAddOpen, setIsAddOpen] = useState(false);
    const [form, setForm] = useState({
        name: "",
        description: "",
        priceMonthly: 0,
        billingCycle: "monthly",
        maxStudents: 500,
        moduleToggles: {
            lms: true,
            finance: true,
            attendance: true,
            exams: true,
            comms: true
        }
    });

    const createMutation = useMutation({
        mutationFn: (data: any) => api.post("/owner/plans", data),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ["owner-plans"] });
            toast.success("New platform tier deployed");
            setIsAddOpen(false);
            setForm({
                name: "",
                description: "",
                priceMonthly: 0,
                billingCycle: "monthly",
                maxStudents: 500,
                moduleToggles: { lms: true, finance: true, attendance: true, exams: true, comms: true }
            });
        },
        onError: (err: any) => toast.error(err?.response?.data?.message || "Deployment failed")
    });

    const deleteMutation = useMutation({
        mutationFn: (id: string) => api.delete(`/owner/plans/${id}`),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ["owner-plans"] });
            toast.success("Tier decommissioned");
        }
    });

    return (
        <div className="p-6 space-y-6">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <h1 className="text-2xl font-heading font-bold">Subscription Tiers</h1>
                    <p className="text-muted-foreground">Manage service plans, pricing, and feature modules for schools.</p>
                </div>
                <Dialog open={isAddOpen} onOpenChange={setIsAddOpen}>
                    <DialogTrigger asChild>
                        <Button className="shrink-0 rounded-xl font-black gap-2 transition-transform hover:scale-105 active:scale-95 shadow-lg shadow-primary/20">
                            <Plus className="w-5 h-5" /> Deploy New Tier
                        </Button>
                    </DialogTrigger>
                    <DialogContent className="max-w-xl rounded-[2.5rem] border-0 shadow-2xl p-0 overflow-hidden bg-background/95 backdrop-blur-xl">
                        <div className="h-2 gradient-primary" />
                        <div className="p-8">
                            <DialogHeader className="mb-8">
                                <DialogTitle className="text-3xl font-heading font-black">Design New Tier</DialogTitle>
                                <DialogDescription className="font-medium">Define pricing, capacity, and active modules for this school tier.</DialogDescription>
                            </DialogHeader>

                            <div className="grid grid-cols-2 gap-6">
                                <div className="space-y-2 col-span-2">
                                    <Label className="text-[10px] font-black uppercase tracking-widest ml-1">Tier Name</Label>
                                    <Input placeholder="e.g. Enterprise Elite" value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} className="h-12 rounded-2xl bg-muted/50 border-0 focus-visible:ring-primary font-bold" />
                                </div>
                                <div className="space-y-2 col-span-2">
                                    <Label className="text-[10px] font-black uppercase tracking-widest ml-1">Market Description</Label>
                                    <Textarea placeholder="Explain what makes this tier unique..." value={form.description} onChange={e => setForm({ ...form, description: e.target.value })} className="rounded-2xl bg-muted/50 border-0 focus-visible:ring-primary min-h-[80px]" />
                                </div>
                                <div className="space-y-2">
                                    <Label className="text-[10px] font-black uppercase tracking-widest ml-1">Monthly Cost (KES)</Label>
                                    <Input type="number" value={form.priceMonthly} onChange={e => setForm({ ...form, priceMonthly: parseFloat(e.target.value) })} className="h-12 rounded-2xl bg-muted/50 border-0 focus-visible:ring-primary font-black" />
                                </div>
                                <div className="space-y-2">
                                    <Label className="text-[10px] font-black uppercase tracking-widest ml-1">Student Capacity</Label>
                                    <Input type="number" value={form.maxStudents} onChange={e => setForm({ ...form, maxStudents: parseInt(e.target.value) })} className="h-12 rounded-2xl bg-muted/50 border-0 focus-visible:ring-primary font-black" />
                                </div>

                                <div className="col-span-2 p-6 rounded-[2rem] bg-accent/30 border border-accent/50 space-y-4">
                                    <p className="text-[10px] text-muted-foreground font-black uppercase tracking-widest flex items-center gap-2">
                                        <Package className="w-3.5 h-3.5" /> Capabilities
                                    </p>
                                    <div className="grid grid-cols-2 gap-x-8 gap-y-4">
                                        {Object.keys(form.moduleToggles).map((mod) => (
                                            <div key={mod} className="flex items-center justify-between">
                                                <Label className="text-xs font-bold uppercase tracking-tight capitalize">{mod} Module</Label>
                                                <Switch
                                                    checked={(form.moduleToggles as any)[mod]}
                                                    onCheckedChange={(v) => setForm({
                                                        ...form,
                                                        moduleToggles: { ...form.moduleToggles, [mod]: v }
                                                    })}
                                                />
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            </div>

                            <DialogFooter className="mt-10 flex !flex-row gap-3">
                                <Button variant="outline" onClick={() => setIsAddOpen(false)} className="flex-1 h-12 rounded-2xl font-bold border-border/50">Abort</Button>
                                <Button onClick={() => createMutation.mutate(form)} disabled={createMutation.isPending} className="flex-[2] h-12 rounded-2xl font-black shadow-lg shadow-primary/20 text-xs">
                                    {createMutation.isPending ? "Deploying..." : "Finalize & Deploy Tier"}
                                </Button>
                            </DialogFooter>
                        </div>
                    </DialogContent>
                </Dialog>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {isLoading ? (
                    <div className="col-span-3 text-center py-20 animate-pulse text-muted-foreground">Fetching platform tiers...</div>
                ) : plans.length === 0 ? (
                    <div className="col-span-3 text-center py-20 text-muted-foreground bg-muted/20 rounded-xl border-2 border-dashed border-muted/50">
                        No subscription plans found. Start by creating the initial tiers.
                    </div>
                ) : plans.map((p: any) => (
                    <Card key={p.id} className="shadow-premium group hover:border-primary/50 transition-all">
                        <CardHeader className="relative">
                            <div className="absolute top-4 right-4 flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                <Button variant="ghost" size="icon" className="h-8 w-8 text-muted-foreground hover:text-primary"><Edit2 className="w-4 h-4" /></Button>
                                <Button variant="ghost" size="icon" className="h-8 w-8 text-muted-foreground hover:text-destructive" onClick={() => deleteMutation.mutate(p.id)}><Trash2 className="w-4 h-4" /></Button>
                            </div>
                            <Badge className="w-fit mb-2 gradient-primary rounded-sm font-mono tracking-widest text-[10px] py-0 px-1.5 border-none shadow-sm">
                                KES {p.priceMonthly.toLocaleString()}/MO
                            </Badge>
                            <CardTitle className="text-xl font-heading">{p.name}</CardTitle>
                            <CardDescription className="line-clamp-2 mt-1 min-h-[40px] text-xs">
                                {p.description || "The core tier for mid-sized school environments."}
                            </CardDescription>
                        </CardHeader>
                        <CardContent className="space-y-4">
                            <div className="grid grid-cols-2 gap-4">
                                <div className="flex items-center gap-2.5">
                                    <div className="w-8 h-8 rounded-lg bg-accent/50 flex items-center justify-center border border-accent">
                                        <Users className="w-4 h-4 text-primary" />
                                    </div>
                                    <div>
                                        <p className="text-[10px] text-muted-foreground uppercase tracking-widest leading-none mb-1">Students</p>
                                        <p className="text-sm font-bold">{p.maxStudents?.toLocaleString() || "UNLIMITED"}</p>
                                    </div>
                                </div>
                                <div className="flex items-center gap-2.5">
                                    <div className="w-8 h-8 rounded-lg bg-accent/50 flex items-center justify-center border border-accent">
                                        <CreditCard className="w-4 h-4 text-primary" />
                                    </div>
                                    <div>
                                        <p className="text-[10px] text-muted-foreground uppercase tracking-widest leading-none mb-1">Billing</p>
                                        <p className="text-sm font-bold uppercase">{p.billingCycle}</p>
                                    </div>
                                </div>
                            </div>

                            <div className="space-y-2 pt-2">
                                <p className="text-[10px] text-muted-foreground uppercase tracking-widest leading-none mb-2">Modules Enabled</p>
                                <div className="flex flex-wrap gap-1.5">
                                    {Object.entries(p.moduleToggles || {}).map(([key, enabled]) => (
                                        enabled && (
                                            <Badge key={key} variant="secondary" className="bg-success/5 text-success/80 border-success/10 text-[10px] font-normal lowercase py-0 shadow-none">
                                                {key}
                                            </Badge>
                                        )
                                    ))}
                                </div>
                            </div>
                        </CardContent>
                        <CardFooter className="pt-4 border-t border-muted/30">
                            <Button variant="outline" size="sm" className="w-full text-xs hover:bg-primary/5 hover:text-primary hover:border-primary/30">View Active Subscriptions</Button>
                        </CardFooter>
                    </Card>
                ))}
            </div>
        </div>
    );
}

import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Lock, Mail, School, User, ShieldCheck } from "lucide-react";
import { toast } from "sonner";
import api from "@/lib/api";

export default function OwnerRegister() {
    const [name, setName] = useState("");
    const [email, setEmail] = useState("");
    const [password, setPassword] = useState("");
    const [loading, setLoading] = useState(false);
    const navigate = useNavigate();

    const handleRegister = async (e: React.FormEvent) => {
        e.preventDefault();
        if (password.length < 6) {
            toast.error("Password must be at least 6 characters");
            return;
        }
        setLoading(true);
        try {
            const res = await api.post("/owner/auth/register", { name, email, password });
            localStorage.setItem("owner_token", res.data.access_token);
            toast.success("Platform account created successfully!");
            navigate("/owner/dashboard");
        } catch (err: any) {
            const msg = err?.response?.data?.message || "Registration failed";
            toast.error(msg);
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="min-h-screen gradient-sidebar flex items-center justify-center p-6">
            <Card className="w-full max-w-md shadow-2xl border-sidebar-border bg-sidebar/50 backdrop-blur-xl">
                <CardHeader className="text-center space-y-1">
                    <div className="mx-auto w-12 h-12 rounded-xl bg-primary flex items-center justify-center mb-4">
                        <ShieldCheck className="w-7 h-7 text-primary-foreground" />
                    </div>
                    <CardTitle className="text-2xl font-heading font-bold text-white">Create Owner Account</CardTitle>
                    <CardDescription className="text-sidebar-foreground/60">
                        Register as a ShuleCloud platform administrator
                    </CardDescription>
                </CardHeader>
                <CardContent>
                    <form onSubmit={handleRegister} className="space-y-4">
                        <div className="relative">
                            <User className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-sidebar-foreground/40" />
                            <Input
                                type="text"
                                placeholder="Full Name"
                                className="pl-10 bg-sidebar-accent/50 border-sidebar-border text-white placeholder:text-sidebar-foreground/30"
                                value={name}
                                onChange={(e) => setName(e.target.value)}
                                required
                            />
                        </div>
                        <div className="relative">
                            <Mail className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-sidebar-foreground/40" />
                            <Input
                                type="email"
                                placeholder="admin@shulecloud.co.ke"
                                className="pl-10 bg-sidebar-accent/50 border-sidebar-border text-white placeholder:text-sidebar-foreground/30"
                                value={email}
                                onChange={(e) => setEmail(e.target.value)}
                                required
                            />
                        </div>
                        <div className="relative">
                            <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-sidebar-foreground/40" />
                            <Input
                                type="password"
                                placeholder="••••••••"
                                className="pl-10 bg-sidebar-accent/50 border-sidebar-border text-white placeholder:text-sidebar-foreground/30"
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                required
                                minLength={6}
                            />
                        </div>
                        <Button type="submit" className="w-full" disabled={loading}>
                            {loading ? "Creating Account..." : "Create Platform Account"}
                        </Button>
                    </form>
                    <div className="mt-6 pt-6 border-t border-sidebar-border text-center space-y-2">
                        <p className="text-sm text-sidebar-foreground/60">
                            Already have an account?{" "}
                            <Link to="/owner" className="text-primary font-semibold hover:underline">
                                Sign In
                            </Link>
                        </p>
                        <p className="text-xs text-sidebar-foreground/40 font-mono tracking-widest uppercase">
                            Authorized Personnel Only
                        </p>
                    </div>
                </CardContent>
            </Card>
        </div>
    );
}

import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import api from "@/lib/api";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Switch } from "@/components/ui/switch";
import { toast } from "sonner";
import { ShieldCheck, AlertCircle } from "lucide-react";

export default function OwnerSettings() {
    const queryClient = useQueryClient();

    const { data: settings, isLoading } = useQuery({
        queryKey: ["owner-settings"],
        queryFn: async () => {
            const res = await api.get("/owner/settings");
            return res.data;
        }
    });

    const updateMutation = useMutation({
        mutationFn: (data: any) => api.patch("/owner/settings", data),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ["owner-settings"] });
            toast.success("Settings updated");
        }
    });

    if (isLoading) return <div className="p-6">Loading settings...</div>;

    return (
        <div className="p-6 space-y-6">
            <div>
                <h1 className="text-2xl font-heading font-bold">Global System Settings</h1>
                <p className="text-muted-foreground">Configure global platform behavior and security policies.</p>
            </div>

            <div className="grid gap-6 max-w-2xl">
                <Card className={settings?.maintenanceMode ? "border-destructive bg-destructive/5" : ""}>
                    <CardHeader>
                        <div className="flex items-center justify-between">
                            <div className="space-y-0.5">
                                <CardTitle className="flex items-center gap-2">
                                    <ShieldCheck className={`w-5 h-5 ${settings?.maintenanceMode ? 'text-destructive' : 'text-success'}`} />
                                    Maintenance Mode
                                </CardTitle>
                                <CardDescription>
                                    When enabled, all school portals will display a maintenance message.
                                </CardDescription>
                            </div>
                            <Switch
                                checked={settings?.maintenanceMode}
                                onCheckedChange={(checked) => updateMutation.mutate({ maintenanceMode: checked })}
                            />
                        </div>
                    </CardHeader>
                    {settings?.maintenanceMode && (
                        <CardContent>
                            <div className="flex items-start gap-3 p-3 rounded-lg bg-destructive/10 text-destructive text-sm border border-destructive/20">
                                <AlertCircle className="w-4 h-4 mt-0.5 shrink-0" />
                                <p>System is currently blocking tenant traffic. Portal owners can still access their dashboards.</p>
                            </div>
                        </CardContent>
                    )}
                </Card>
            </div>
        </div>
    );
}

