    const [showPlanDialog, setShowPlanDialog] = useState(false);
    const queryClient = useQueryClient();

    const { data: tenants = [], isLoading } = useQuery({
        queryKey: ["owner-tenants"],
        queryFn: async () => {
            const res = await api.get("/owner/tenants");
            return res.data;
        }
    });

    const { data: plans = [] } = useQuery({
        queryKey: ["owner-plans"],
        queryFn: async () => {
            const res = await api.get("/owner/plans");
            return res.data;
        }
    });

    const assignPlanMutation = useMutation({
        mutationFn: ({ tenantId, planId }: { tenantId: string, planId: string }) =>
            api.post(`/owner/subscriptions/${tenantId}/assign-plan`, { planId }),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ["owner-tenants"] });
            setShowPlanDialog(false);
            toast.success("Subscription plan updated");
        }
    });

    const suspendMutation = useMutation({
        mutationFn: (id: string) => api.post(`/owner/tenants/${id}/suspend`),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ["owner-tenants"] });
            toast.success("Tenant suspended");
        }
    });

    const reactivateMutation = useMutation({
        mutationFn: (id: string) => api.post(`/owner/tenants/${id}/reactivate`),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ["owner-tenants"] });
            toast.success("Tenant reactivated");
        }
    });

    const filteredTenants = tenants.filter((t: any) =>
        t.name.toLowerCase().includes(search.toLowerCase()) ||
        t.domains?.[0]?.domain?.toLowerCase().includes(search.toLowerCase())
    );

    return (
        <div className="p-6 space-y-6">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <h1 className="text-2xl font-heading font-bold">Tenant Management</h1>
                    <p className="text-muted-foreground">Monitor and manage school environments across the platform.</p>
                </div>
                <Button className="shrink-0"><Plus className="w-4 h-4 mr-2" /> Provision School</Button>
            </div>

            <Card>
                <CardHeader className="pb-3">
                    <div className="flex items-center gap-4">
                        <div className="relative flex-1 max-w-sm">
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                            <Input
                                placeholder="Search schools or subdomains..."
                                className="pl-9"
                                value={search}
                                onChange={(e) => setSearch(e.target.value)}
                            />
                        </div>
                        <Badge variant="outline" className="h-9 px-3 font-normal text-muted-foreground">
                            {filteredTenants.length} Total Schools
                        </Badge>
                    </div>
                </CardHeader>
                <CardContent className="p-0">
                    <Table>
                        <TableHeader>
                            <TableRow>
                                <TableHead>SCHOOL NAME</TableHead>
                                <TableHead>SUBDOMAIN</TableHead>
                                <TableHead>STATUS</TableHead>
                                <TableHead>SUBSCRIPTION</TableHead>
                                <TableHead>CREATED</TableHead>
                                <TableHead className="w-12"></TableHead>
                            </TableRow>
                        </TableHeader>
                        <TableBody>
                            {isLoading ? (
                                <TableRow><TableCell colSpan={6} className="text-center py-10 animate-pulse">Fetching schools...</TableCell></TableRow>
                            ) : filteredTenants.length === 0 ? (
                                <TableRow><TableCell colSpan={6} className="text-center py-10">No schools found.</TableCell></TableRow>
                            ) : filteredTenants.map((t: any) => (
                                <TableRow key={t.id}>
                                    <TableCell className="font-medium">{t.name}</TableCell>
                                    <TableCell>
                                        <code className="text-xs bg-muted px-1.5 py-0.5 rounded text-primary">
                                            {t.domains?.[0]?.domain}.shulecloud.co.ke
                                        </code>
                                    </TableCell>
                                    <TableCell>
                                        <Badge className={t.status === 'active' ? 'bg-success/10 text-success' : 'bg-destructive/10 text-destructive'}>
                                            {t.status}
                                        </Badge>
                                    </TableCell>
                                    <TableCell>
                                        <div className="text-sm">{t.subscription?.plan?.name || 'No Plan'}</div>
                                        <div className="text-xs text-muted-foreground">Expires: {t.subscription?.currentPeriodEnd ? new Date(t.subscription.currentPeriodEnd).toLocaleDateString() : 'N/A'}</div>
                                    </TableCell>
                                    <TableCell className="text-sm text-muted-foreground">
                                        {new Date(t.createdAt).toLocaleDateString()}
                                    </TableCell>
                                    <TableCell>
                                        <DropdownMenu>
                                            <DropdownMenuTrigger asChild>
                                                <Button variant="ghost" size="icon" className="h-8 w-8"><MoreVertical className="w-4 h-4" /></Button>
                                            </DropdownMenuTrigger>
                                            <DropdownMenuContent align="end">
                                                <DropdownMenuItem onClick={() => toast.info("Details coming soon")}>View Dashboard</DropdownMenuItem>
                                                <DropdownMenuItem onClick={() => { setSelectedTenant(t); setShowPlanDialog(true); }}>
                                                    <CreditCard className="w-4 h-4 mr-2" /> Change Plan
                                                </DropdownMenuItem>
                                                {t.status === 'active' ? (
                                                    <DropdownMenuItem className="text-destructive" onClick={() => suspendMutation.mutate(t.id)}>
                                                        <Ban className="w-4 h-4 mr-2" /> Suspend
                                                    </DropdownMenuItem>
                                                ) : (
                                                    <DropdownMenuItem className="text-success" onClick={() => reactivateMutation.mutate(t.id)}>
                                                        <RefreshCw className="w-4 h-4 mr-2" /> Reactivate
                                                    </DropdownMenuItem>
                                                )}
                                            </DropdownMenuContent>
                                        </DropdownMenu>
                                    </TableCell>
                                </TableRow>
                            ))}
                        </TableBody>
                    </Table>
                </CardContent>
            </Card>

            <Dialog open={showPlanDialog} onOpenChange={setShowPlanDialog}>
                <DialogContent className="max-w-md">
                    <DialogHeader>
                        <DialogTitle>Change Subscription Plan</DialogTitle>
                        <DialogDescription>
                            Select a new service tier for <strong>{selectedTenant?.name}</strong>.
                        </DialogDescription>
                    </DialogHeader>
                    <div className="space-y-4 py-4">
                        {plans.map((p: any) => (
                            <div
                                key={p.id}
                                className={`p-4 rounded-xl border-2 cursor-pointer transition-all flex items-center justify-between group ${selectedTenant?.subscription?.planId === p.id ? 'border-primary bg-primary/5' : 'border-muted hover:border-primary/30'}`}
                                onClick={() => assignPlanMutation.mutate({ tenantId: selectedTenant.id, planId: p.id })}
                            >
                                <div className="space-y-1">
                                    <p className="font-bold flex items-center gap-2">
                                        {p.name}
                                        {selectedTenant?.subscription?.planId === p.id && <Badge className="h-5 px-1.5 bg-primary/20 text-primary border-none text-[8px] font-black uppercase">Active</Badge>}
                                    </p>
                                    <p className="text-xs text-muted-foreground">{p.description || "School management tier."}</p>
                                </div>
                                <div className="text-right">
                                    <p className="text-sm font-black">KES {p.priceMonthly.toLocaleString()}</p>
                                    <p className="text-[10px] text-muted-foreground uppercase font-bold tracking-widest">/MO</p>
                                </div>
                            </div>
                        ))}
                    </div>
                </DialogContent>
            </Dialog>
        </div>
    );
}

import { Link } from "react-router-dom";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Check, School, ArrowRight } from "lucide-react";

import { useQuery } from "@tanstack/react-query";
import api from "@/lib/api";

export default function Pricing() {
  const { data: plans = [], isLoading } = useQuery({
    queryKey: ["plans"],
    queryFn: async () => {
      const res = await api.get("/plans");
      return res.data;
    }
  });

  return (
    <div className="min-h-screen bg-background">
      <nav className="border-b border-border bg-card/80 backdrop-blur-sm sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-6 h-16 flex items-center justify-between">
          <Link to="/" className="flex items-center gap-2.5">
            <div className="w-9 h-9 rounded-lg gradient-primary flex items-center justify-center">
              <School className="w-5 h-5 text-primary-foreground" />
            </div>
            <span className="font-heading text-xl font-bold text-foreground">ShuleCloud</span>
          </Link>
          <div className="hidden md:flex items-center gap-8">
            <Link to="/features" className="text-sm text-muted-foreground hover:text-foreground">Features</Link>
            <Link to="/pricing" className="text-sm font-medium text-foreground">Pricing</Link>
            <Link to="/contact" className="text-sm text-muted-foreground hover:text-foreground">Contact</Link>
          </div>
          <Button size="sm" asChild><Link to="/login">Sign In</Link></Button>
        </div>
      </nav>

      <div className="max-w-7xl mx-auto px-6 py-20">
        <div className="text-center mb-16">
          <h1 className="font-heading text-4xl md:text-5xl font-bold text-foreground">Simple, Transparent Pricing</h1>
          <p className="mt-4 text-lg text-muted-foreground max-w-xl mx-auto">All plans include a 30-day free trial. No setup fees. Cancel anytime.</p>
          <p className="mt-2 text-sm text-muted-foreground">All prices in KES. Annual billing available at 20% discount.</p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 max-w-5xl mx-auto">
          {isLoading ? (
            <div className="col-span-3 text-center py-20 text-muted-foreground animate-pulse">Loading pricing plans...</div>
          ) : plans.length === 0 ? (
            <div className="col-span-3 text-center py-20 text-muted-foreground">No plans currently available. Please contact us.</div>
          ) : (
            plans.map((plan: any) => (
              <Card key={plan.id} className={`relative shadow-card hover:shadow-card-hover transition-all ${plan.name === 'Premium' ? "border-primary border-2 scale-[1.02]" : ""}`}>
                {plan.name === 'Premium' && (
                  <div className="absolute -top-3 left-1/2 -translate-x-1/2">
                    <Badge className="gradient-gold text-secondary-foreground border-0 px-4">Most Popular</Badge>
                  </div>
                )}
                <CardHeader className="pb-2">
                  <CardTitle className="font-heading text-lg">{plan.name}</CardTitle>
                  <p className="text-sm text-muted-foreground">Comprehensive school management</p>
                  <div className="pt-3">
                    <span className="text-4xl font-heading font-bold text-foreground">KES {Number(plan.price).toLocaleString()}</span>
                    <span className="text-muted-foreground text-sm">/{plan.cycle.toLowerCase().replace('ly', '')}</span>
                  </div>
                </CardHeader>
                <CardContent className="space-y-4">
                  <Button className="w-full" variant={plan.name === 'Premium' ? "default" : "outline"} asChild>
                    <Link to="/register">Start Free Trial <ArrowRight className="w-4 h-4 ml-1" /></Link>
                  </Button>
                  <div className="space-y-2.5 pt-2">
                    <div className="flex items-start gap-2.5">
                      <Check className="w-4 h-4 text-success flex-shrink-0 mt-0.5" />
                      <span className="text-sm text-foreground">Up to {plan.limits?.maxStudents?.toLocaleString() || 'Unlimited'} students</span>
                    </div>
                    {Object.entries(plan.moduleToggles || {}).map(([key, value]) => value && (
                      <div key={key} className="flex items-start gap-2.5">
                        <Check className="w-4 h-4 text-success flex-shrink-0 mt-0.5" />
                        <span className="text-sm text-foreground capitalize">{key} Module</span>
                      </div>
                    ))}
                    <div className="flex items-start gap-2.5">
                      <Check className="w-4 h-4 text-success flex-shrink-0 mt-0.5" />
                      <span className="text-sm text-foreground italic">{plan.cycle} billing</span>
                    </div>
                  </div>
                </CardContent>
              </Card>
            ))
          )}
        </div>
      </div>
    </div>
  );
}

import { useState } from "react";
import { useNavigate, Link } from "react-router-dom";
import { School, Eye, EyeOff, ArrowRight, Building2, User, Mail, Lock, Globe } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { toast } from "sonner";
import api from "@/lib/api";

export default function Register() {
  const navigate = useNavigate();
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  const [formData, setFormData] = useState({
    schoolName: "",
    subdomain: "",
    adminName: "",
    adminEmail: "",
    password: "",
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { id, value } = e.target;
    if (id === 'subdomain') {
      // Only allow lowercase, numbers, hyphens
      setFormData(prev => ({ ...prev, [id]: value.toLowerCase().replace(/[^a-z0-9-]/g, '') }));
    } else {
      setFormData(prev => ({ ...prev, [id]: value }));
    }
  };

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();

    if (formData.password.length < 6) {
      toast.error("Password must be at least 6 characters");
      return;
    }
    if (!formData.subdomain) {
      toast.error("Please enter a school subdomain");
      return;
    }

    setIsLoading(true);
    try {
      const res = await api.post("/onboard/register-tenant", formData);
      // Store tokens if returned
      if (res.data.access_token) {
        localStorage.setItem("auth_token", res.data.access_token);
        localStorage.setItem("refresh_token", res.data.refresh_token);
      }
      toast.success("School account created successfully! Welcome to ShuleCloud.");
      navigate("/onboarding");
    } catch (err: any) {
      const msg = err?.response?.data?.message || "Registration failed. Please try again.";
      toast.error(msg);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex">
      {/* Left Panel - Information/Visuals */}
      <div className="hidden lg:flex lg:w-1/2 gradient-primary relative overflow-hidden items-center justify-center p-12">
        <div className="absolute inset-0 opacity-10">
          <div className="absolute top-20 left-20 w-64 h-64 rounded-full border border-primary-foreground/20" />
          <div className="absolute bottom-32 right-16 w-96 h-96 rounded-full border border-primary-foreground/20" />
          <div className="absolute top-1/2 left-1/3 w-48 h-48 rounded-full border border-primary-foreground/20" />
        </div>
        <div className="relative z-10 max-w-md text-center space-y-6">
          <div className="w-16 h-16 rounded-2xl gradient-gold flex items-center justify-center mx-auto">
            <School className="w-8 h-8 text-secondary-foreground" />
          </div>
          <h1 className="text-4xl font-heading font-bold text-primary-foreground">Join ShuleCloud</h1>
          <p className="text-primary-foreground/80 text-lg leading-relaxed">
            Take the first step towards a smarter, CBC-compliant school management experience. Trusted by hundreds of schools across Kenya.
          </p>

          <div className="space-y-4 pt-6 text-left">
            {[
              { icon: Building2, text: "Multi-campus Support" },
              { icon: Globe, text: "Your Own School Portal" },
              { icon: ArrowRight, text: "Instant CBC Report Cards" }
            ].map((item, i) => (
              <div key={i} className="flex items-center gap-3 bg-primary-foreground/10 p-3 rounded-lg backdrop-blur-sm border border-primary-foreground/10">
                <div className="w-8 h-8 rounded-md bg-secondary/20 flex items-center justify-center">
                  <item.icon className="w-4 h-4 text-secondary" />
                </div>
                <span className="text-primary-foreground font-medium">{item.text}</span>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Right Panel - Form */}
      <div className="flex-1 flex items-center justify-center p-8 bg-background overflow-y-auto">
        <div className="w-full max-w-md space-y-8 py-12">
          <div className="lg:hidden flex items-center gap-3 justify-center mb-8">
            <div className="w-10 h-10 rounded-xl gradient-primary flex items-center justify-center">
              <School className="w-5 h-5 text-primary-foreground" />
            </div>
            <h1 className="text-2xl font-heading font-bold text-foreground">ShuleCloud</h1>
          </div>

          <div className="space-y-2">
            <h2 className="text-2xl font-heading font-bold text-foreground">Create school account</h2>
            <p className="text-muted-foreground">Start your 14-day free trial today</p>
          </div>

          <form onSubmit={handleRegister} className="space-y-5">
            <div className="grid grid-cols-1 gap-5">
              {/* School Information */}
              <div className="space-y-4">
                <div className="space-y-2">
                  <Label htmlFor="schoolName">School Name</Label>
                  <div className="relative">
                    <Building2 className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                    <Input
                      id="schoolName"
                      placeholder="e.g. Kings High School"
                      value={formData.schoolName}
                      onChange={handleChange}
                      className="h-11 pl-10"
                      required
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="subdomain">School Short Name / Subdomain</Label>
                  <div className="relative">
                    <Globe className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                    <Input
                      id="subdomain"
                      placeholder="e.g. kingshigh"
                      value={formData.subdomain}
                      onChange={handleChange}
                      className="h-11 pl-10 pr-32"
                      required
                    />
                    <div className="absolute right-3 top-1/2 -translate-y-1/2 text-xs font-medium text-muted-foreground bg-muted px-2 py-1 rounded">
                      .shulecloud.co.ke
                    </div>
                  </div>
                  <p className="text-[10px] text-muted-foreground">This will be your school's unique URL</p>
                </div>
              </div>

              <div className="h-px bg-border my-2" />

              {/* Admin Information */}
              <div className="space-y-4">
                <div className="space-y-2">
                  <Label htmlFor="adminName">Administrator Full Name</Label>
                  <div className="relative">
                    <User className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                    <Input
                      id="adminName"
                      placeholder="John Doe"
                      value={formData.adminName}
                      onChange={handleChange}
                      className="h-11 pl-10"
                      required
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="adminEmail">Email Address</Label>
                  <div className="relative">
                    <Mail className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                    <Input
                      id="adminEmail"
                      type="email"
                      placeholder="admin@school.com"
                      value={formData.adminEmail}
                      onChange={handleChange}
                      className="h-11 pl-10"
                      required
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="password">Password</Label>
                  <div className="relative">
                    <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                    <Input
                      id="password"
                      type={showPassword ? "text" : "password"}
                      placeholder="••••••••"
                      value={formData.password}
                      onChange={handleChange}
                      className="h-11 pl-10 pr-10"
                      required
                      minLength={6}
                    />
                    <button
                      type="button"
                      onClick={() => setShowPassword(!showPassword)}
                      className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
                    >
                      {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                    </button>
                  </div>
                </div>
              </div>
            </div>

            <Button type="submit" className="w-full h-11 font-medium mt-4" disabled={isLoading}>
              {isLoading ? "Creating Account..." : "Create Account"}
            </Button>
          </form>

          <div className="text-center space-y-4">
            <p className="text-sm text-muted-foreground">
              Already have an account?{" "}
              <Link to="/login" className="text-primary font-semibold hover:underline">
                Sign In
              </Link>
            </p>
            <p className="text-[10px] text-muted-foreground leading-relaxed">
              By creating an account, you agree to our{" "}
              <Link to="/terms" className="underline">Terms of Service</Link> and{" "}
              <Link to="/privacy" className="underline">Privacy Policy</Link>.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { School, Eye, EyeOff } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { toast } from "sonner";
import api from "@/lib/api";

export default function Login() {
  const navigate = useNavigate();
  const [showPassword, setShowPassword] = useState(false);
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [subdomain, setSubdomain] = useState("");
  const [isLoading, setIsLoading] = useState(false);

  // Auto-detect subdomain from URL if applicable
  const detectedSubdomain = (() => {
    const host = window.location.hostname;
    const parts = host.split('.');
    if (parts.length > 2 && parts[0] !== 'www') return parts[0];
    return '';
  })();

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    const actualSubdomain = detectedSubdomain || subdomain;
    if (!actualSubdomain) {
      toast.error("Please enter your school subdomain");
      return;
    }
    setIsLoading(true);
    try {
      const res = await api.post("/auth/login", {
        email,
        password,
        subdomain: actualSubdomain,
      });
      // Store tokens and user info
      localStorage.setItem("auth_token", res.data.access_token);
      localStorage.setItem("refresh_token", res.data.refresh_token);
      localStorage.setItem("user", JSON.stringify(res.data.user));
      localStorage.setItem("tenant", JSON.stringify(res.data.tenant));
      toast.success(`Welcome back, ${res.data.user.firstName}!`);
      navigate("/dashboard");
    } catch (err: any) {
      const msg = err?.response?.data?.message || "Login failed. Please check your credentials.";
      toast.error(msg);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex">
      {/* Left Panel */}
      <div className="hidden lg:flex lg:w-1/2 gradient-primary relative overflow-hidden items-center justify-center p-12">
        <div className="absolute inset-0 opacity-10">
          <div className="absolute top-20 left-20 w-64 h-64 rounded-full border border-primary-foreground/20" />
          <div className="absolute bottom-32 right-16 w-96 h-96 rounded-full border border-primary-foreground/20" />
          <div className="absolute top-1/2 left-1/3 w-48 h-48 rounded-full border border-primary-foreground/20" />
        </div>
        <div className="relative z-10 max-w-md text-center space-y-6">
          <div className="w-16 h-16 rounded-2xl gradient-gold flex items-center justify-center mx-auto">
            <School className="w-8 h-8 text-secondary-foreground" />
          </div>
          <h1 className="text-4xl font-heading font-bold text-primary-foreground">ShuleCloud</h1>
          <p className="text-primary-foreground/80 text-lg leading-relaxed">
            Kenya's premier CBC-compliant school management platform. Streamline administration, empower teachers, engage parents.
          </p>
          <div className="flex items-center justify-center gap-6 pt-4">
            {["200+ Schools", "50K+ Students", "CBC Ready"].map(stat => (
              <div key={stat} className="text-center">
                <p className="text-sm font-medium text-primary-foreground/90">{stat}</p>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Right Panel */}
      <div className="flex-1 flex items-center justify-center p-8 bg-background">
        <div className="w-full max-w-md space-y-8">
          <div className="lg:hidden flex items-center gap-3 justify-center mb-8">
            <div className="w-10 h-10 rounded-xl gradient-primary flex items-center justify-center">
              <School className="w-5 h-5 text-primary-foreground" />
            </div>
            <h1 className="text-2xl font-heading font-bold text-foreground">ShuleCloud</h1>
          </div>

          <div className="space-y-2">
            <h2 className="text-2xl font-heading font-bold text-foreground">Welcome back</h2>
            <p className="text-muted-foreground">Sign in to your school portal</p>
          </div>

          <form onSubmit={handleLogin} className="space-y-5">
            {/* Show subdomain field only when not detected from URL */}
            {!detectedSubdomain && (
              <div className="space-y-2">
                <Label htmlFor="subdomain">School Subdomain</Label>
                <div className="relative">
                  <Input
                    id="subdomain"
                    type="text"
                    placeholder="e.g. kingshigh"
                    value={subdomain}
                    onChange={e => setSubdomain(e.target.value.toLowerCase().replace(/[^a-z0-9-]/g, ''))}
                    className="h-11 pr-32"
                    required
                  />
                  <div className="absolute right-3 top-1/2 -translate-y-1/2 text-xs font-medium text-muted-foreground bg-muted px-2 py-1 rounded">
                    .shulecloud.co.ke
                  </div>
                </div>
              </div>
            )}

            <div className="space-y-2">
              <Label htmlFor="email">Email Address</Label>
              <Input
                id="email"
                type="email"
                placeholder="admin@school.ke"
                value={email}
                onChange={e => setEmail(e.target.value)}
                className="h-11"
                required
              />
            </div>

            <div className="space-y-2">
              <div className="flex items-center justify-between">
                <Label htmlFor="password">Password</Label>
                <Link to="/forgot-password" className="text-xs text-primary hover:underline">Forgot password?</Link>
              </div>
              <div className="relative">
                <Input
                  id="password"
                  type={showPassword ? "text" : "password"}
                  placeholder="••••••••"
                  value={password}
                  onChange={e => setPassword(e.target.value)}
                  className="h-11 pr-10"
                  required
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
                >
                  {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                </button>
              </div>
            </div>

            <Button type="submit" className="w-full h-11 font-medium" disabled={isLoading}>
              {isLoading ? "Signing in..." : "Sign In"}
            </Button>
          </form>

          <p className="text-center text-sm text-muted-foreground my-4">
            Don't have an account?{" "}
            <Link to="/register" className="text-primary font-semibold hover:underline">
              Register School
            </Link>
          </p>

          <p className="text-center text-xs text-muted-foreground">
            Powered by ShuleCloud · CBC Compliant · Secure & Reliable
          </p>
        </div>
      </div>
    </div>
  );
}

import { useState } from "react";
import AppHeader from "@/components/AppHeader";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Search, BookOpen, Layers, CheckCircle2, Plus, ArrowRight, Sparkles, GraduationCap } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import api from "@/lib/api";
import { toast } from "sonner";
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter, DialogDescription,
} from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { motion, AnimatePresence } from "framer-motion";

export default function Academics() {
  const [search, setSearch] = useState("");
  const [showAdd, setShowAdd] = useState(false);
  const [newLA, setNewLA] = useState({ name: "" });
  const queryClient = useQueryClient();

  const { data: learningAreas = [], isLoading } = useQuery({
    queryKey: ["learning-areas"],
    queryFn: async () => {
      const r = await api.get("/academics/learning-areas");
      return r.data;
    },
  });

  const createMutation = useMutation({
    mutationFn: (data: any) => api.post("/academics/learning-areas", data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["learning-areas"] });
      setShowAdd(false);
      setNewLA({ name: "" });
      toast.success("New learning area registered successfully");
    },
    onError: (err: any) => toast.error(err?.response?.data?.message || "Failed to create learning area"),
  });

  const filtered = learningAreas.filter((la: any) =>
    la.name.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <>
      <AppHeader title="Academics" subtitle="CBC Learning Areas & Competency Framework" />
      <div className="flex-1 overflow-y-auto p-6 space-y-8 bg-muted/30">

        {/* Hero Section / Stats */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <Card className="border-0 shadow-soft bg-gradient-to-br from-primary/10 to-transparent backdrop-blur-md">
            <CardContent className="p-6 flex items-center gap-4">
              <div className="w-14 h-14 rounded-2xl bg-primary/20 flex items-center justify-center border border-primary/20">
                <BookOpen className="w-7 h-7 text-primary" />
              </div>
              <div>
                <p className="text-[10px] font-black uppercase tracking-[0.2em] text-primary/60">Total Areas</p>
                <p className="text-3xl font-black">{isLoading ? "---" : learningAreas.length}</p>
              </div>
            </CardContent>
          </Card>

          <Card className="border-0 shadow-soft bg-background/50 backdrop-blur-md">
            <CardContent className="p-6 flex items-center gap-4">
              <div className="w-14 h-14 rounded-2xl bg-indigo-500/10 flex items-center justify-center border border-indigo-500/20">
                <Layers className="w-7 h-7 text-indigo-500" />
              </div>
              <div>
                <p className="text-[10px] font-black uppercase tracking-[0.2em] text-indigo-500/60">System Strands</p>
                <p className="text-3xl font-black">
                  {learningAreas.reduce((acc: number, la: any) => acc + (la.strands?.length || 0), 0)}
                </p>
              </div>
            </CardContent>
          </Card>

          <Card className="border-0 shadow-soft bg-background/50 backdrop-blur-md">
            <CardContent className="p-6 flex items-center gap-4">
              <div className="w-14 h-14 rounded-2xl bg-success/10 flex items-center justify-center border border-success/20">
                <Sparkles className="w-7 h-7 text-success" />
              </div>
              <div>
                <p className="text-[10px] font-black uppercase tracking-[0.2em] text-success/60">Active Framework</p>
                <p className="text-sm font-black mt-1">CBC Version 2.4.1</p>
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Toolbar */}
        <div className="flex flex-col sm:flex-row justify-between items-center gap-4 bg-background/40 p-4 rounded-[2rem] border border-border/50 backdrop-blur-md">
          <div className="relative w-full sm:w-96">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
            <Input
              placeholder="Search curriculum areas..."
              value={search}
              onChange={e => setSearch(e.target.value)}
              className="pl-11 h-12 bg-background/50 border-none rounded-2xl shadow-none focus-visible:ring-2 focus-visible:ring-primary/20"
            />
          </div>
          <Button onClick={() => setShowAdd(true)} className="w-full sm:w-auto h-12 px-8 rounded-2xl shadow-lg shadow-primary/20 font-bold gap-2">
            <Plus className="w-5 h-5" /> Register New Area
          </Button>
        </div>

        {/* Areas Grid */}
        <AnimatePresence mode="wait">
          {isLoading ? (
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex flex-col items-center justify-center py-32 gap-4">
              <div className="w-10 h-10 border-4 border-primary/10 border-t-primary rounded-full animate-spin" />
              <p className="text-xs font-bold uppercase tracking-widest text-muted-foreground">Indexing Curriculum...</p>
            </motion.div>
          ) : filtered.length === 0 ? (
            <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} className="text-center py-32 bg-background/20 rounded-[3rem] border-2 border-dashed border-border/50">
              <BookOpen className="w-16 h-16 text-muted-foreground/20 mx-auto mb-6" />
              <h3 className="text-xl font-black mb-2">No Areas Found</h3>
              <p className="text-muted-foreground text-sm max-w-xs mx-auto">Start building your school's academic framework by adding your first learning area.</p>
            </motion.div>
          ) : (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6"
            >
              {filtered.map((la: any, idx: number) => (
                <motion.div
                  initial={{ opacity: 0, y: 30 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: idx * 0.05 }}
                  key={la.id}
                >
                  <Card className="shadow-soft hover:shadow-2xl transition-all duration-500 border-0 bg-background/60 backdrop-blur-md group overflow-hidden rounded-[2rem] cursor-pointer">
                    <div className="h-2 w-full bg-gradient-to-r from-primary to-indigo-500 opacity-20 group-hover:opacity-100 transition-opacity" />
                    <CardHeader className="pb-4">
                      <div className="flex items-start justify-between">
                        <div className="bg-primary/10 p-3 rounded-2xl border border-primary/10 group-hover:scale-110 transition-transform duration-500">
                          <GraduationCap className="w-6 h-6 text-primary" />
                        </div>
                        <Badge variant="secondary" className="bg-success/10 text-success border-none text-[10px] font-black h-5 uppercase tracking-tighter">
                          System Default
                        </Badge>
                      </div>
                      <CardTitle className="text-xl font-black mt-4 leading-tight group-hover:text-primary transition-colors">{la.name}</CardTitle>
                    </CardHeader>
                    <CardContent className="space-y-6">
                      <div className="grid grid-cols-2 gap-4 pt-4 border-t border-dashed border-border/50">
                        <div className="flex flex-col">
                          <span className="text-2xl font-black text-foreground">{la.strands?.length || 0}</span>
                          <span className="text-[9px] uppercase font-black text-muted-foreground tracking-widest flex items-center gap-1.5">
                            <Layers className="w-2.5 h-2.5" /> Strands
                          </span>
                        </div>
                        <div className="flex flex-col">
                          <span className="text-2xl font-black text-foreground">
                            {la.strands?.reduce((acc: number, s: any) => acc + (s.subStrands?.reduce((acc2: number, ss: any) => acc2 + (ss.competencies?.length || 0), 0) || 0), 0) || 0}
                          </span>
                          <span className="text-[9px] uppercase font-black text-muted-foreground tracking-widest flex items-center gap-1.5">
                            <CheckCircle2 className="w-2.5 h-2.5" /> Skills
                          </span>
                        </div>
                      </div>
                      <Button variant="ghost" className="w-full justify-between h-10 px-0 hover:bg-transparent group-hover:text-primary transition-colors text-xs font-bold uppercase tracking-widest">
                        Manage Curriculum <ArrowRight className="w-4 h-4 group-hover:translate-x-1 transition-transform" />
                      </Button>
                    </CardContent>
                  </Card>
                </motion.div>
              ))}
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      <Dialog open={showAdd} onOpenChange={setShowAdd}>
        <DialogContent className="rounded-[2.5rem] p-0 border-0 shadow-2xl overflow-hidden max-w-sm">
          <div className="h-2 bg-primary" />
          <div className="p-8">
            <DialogHeader className="mb-6">
              <DialogTitle className="text-2xl font-black">Register Area</DialogTitle>
              <DialogDescription className="text-xs font-medium">Add a new learning area to the school's dynamic curriculum framework.</DialogDescription>
            </DialogHeader>
            <div className="space-y-6">
              <div className="space-y-2">
                <Label className="text-[10px] font-bold uppercase tracking-widest ml-1">Learning Area Name</Label>
                <Input
                  placeholder="e.g. Creative Arts & Sports"
                  value={newLA.name}
                  onChange={e => setNewLA({ ...newLA, name: e.target.value })}
                  className="h-12 bg-muted/50 border-0 rounded-2xl focus-visible:ring-primary"
                />
              </div>
            </div>
            <DialogFooter className="mt-8 flex !flex-row gap-2">
              <Button variant="outline" onClick={() => setShowAdd(false)} className="flex-1 h-12 rounded-2xl font-bold">Cancel</Button>
              <Button
                onClick={() => createMutation.mutate(newLA)}
                disabled={createMutation.isPending || !newLA.name}
                className="flex-1 h-12 rounded-2xl font-bold shadow-lg shadow-primary/20"
              >
                {createMutation.isPending ? "Creating..." : "Save Area"}
              </Button>
            </DialogFooter>
          </div>
        </DialogContent>
      </Dialog>
    </>
  );
}

import { useState } from "react";

import {
    Search, Plus, UserPlus, ClipboardCheck, Calendar, CheckCircle2, XCircle,
    MoreVertical, Pencil, Trash2, Eye, GraduationCap, Users, School,
